-- Hand-written migration (NOT generated by `prisma migrate dev`).
-- Prisma's schema language cannot express CHECK constraints, so this
-- constraint is maintained manually, separate from the generated baseline.
--
-- CHECK survival mechanics (see openspec/changes/money-stock-integrity/design.md
-- "Decision: migration ordering, and how the CHECK survives"):
--   1. This migration file is never folded into a generated baseline, so it
--      replays on every `migrate reset` / `migrate deploy`.
--   2. `schema.prisma` carries a comment above `model product` pointing back
--      here, so a future baseline regeneration is not silently missing it.
--   3. `tests/integrity/stock-check.test.js` queries `pg_constraint` directly
--      and asserts a negative stock UPDATE is rejected — the only thing that
--      actually catches a future regeneration omitting this constraint.
ALTER TABLE "product" ADD CONSTRAINT "product_stock_non_negative" CHECK ("stock" >= 0);
